<?php
require __DIR__.'/includes/bootstrap.php';require_auth();require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';
$action=$_GET['action']??'';$id=(int)($_GET['id']??0);if($_SERVER['REQUEST_METHOD']==='POST'||in_array($action,['create','edit'],true))require_permission('sales.create');
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$id=(int)($_POST['id']??0);$date=$_POST['sale_date']??date('Y-m-d');$branch=(int)($_POST['branch_id']??0);$brand=(int)($_POST['brand_id']??0);$total=max(0,(float)($_POST['total_amount']??0));$cash=max(0,(float)($_POST['cash_amount']??0));$card=max(0,(float)($_POST['card_amount']??0));$talabat=max(0,(float)($_POST['talabat_amount']??0));$keeta=max(0,(float)($_POST['keeta_amount']??0));$snoonu=max(0,(float)($_POST['snoonu_amount']??0));$notes=trim((string)($_POST['notes']??''));$breakdown=round($cash+$card+$talabat+$keeta+$snoonu,2);
    if(!$branch||!$brand||$total<=0){flash('error','Choose branch and brand, then enter the total end-of-day sale.');redirect('sales.php?action='.($id?'edit&id='.$id:'create'));}
    if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$date>date('Y-m-d')){flash('error','Choose a valid sales date that is not in the future.');redirect('sales.php?action='.($id?'edit&id='.$id:'create'));}
    if(abs($total-$breakdown)>0.01){flash('error','Cash, Card, Talabat, Keeta and Snoonu must equal the total sale. Difference: '.money(abs($total-$breakdown)).'.');redirect('sales.php?action='.($id?'edit&id='.$id:'create'));}
    try{enforce_branch_scope($branch);$pdo->beginTransaction();$check=$pdo->prepare('SELECT id FROM sales WHERE sale_date=? AND branch_id=? AND brand_id=? AND id<>? AND deleted_at IS NULL LIMIT 1');$check->execute([$date,$branch,$brand,$id]);if($check->fetchColumn())throw new RuntimeException('A sales summary already exists for this date, branch and brand. Edit that existing record instead.');if($id){$s=$pdo->prepare('UPDATE sales SET sale_date=?,branch_id=?,brand_id=?,subtotal=?,total_amount=?,cash_amount=?,card_amount=?,talabat_amount=?,keeta_amount=?,snoonu_amount=?,notes=? WHERE id=? AND deleted_at IS NULL');$s->execute([$date,$branch,$brand,$total,$total,$cash,$card,$talabat,$keeta,$snoonu,$notes,$id]);audit($pdo,'update','daily_sales',$id,null,['date'=>$date,'total'=>$total]);$message='Daily sales summary updated.';}else{$ref=next_reference($pdo,'DAY','sales');$s=$pdo->prepare('INSERT INTO sales(reference_no,sale_date,branch_id,brand_id,subtotal,total_amount,cash_amount,card_amount,talabat_amount,keeta_amount,snoonu_amount,notes,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,? ,"completed",?)');$s->execute([$ref,$date,$branch,$brand,$total,$total,$cash,$card,$talabat,$keeta,$snoonu,$notes,user()['id']]);$id=(int)$pdo->lastInsertId();audit($pdo,'create','daily_sales',$id,null,['reference'=>$ref,'date'=>$date,'total'=>$total]);$message='End-of-day sales saved successfully.';}$pdo->commit();flash('success',$message);redirect('sales.php?from='.$date.'&to='.$date);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());redirect('sales.php?action='.($id?'edit&id='.$id:'create'));}
}
$sale=[];if($id){$q=$pdo->prepare('SELECT * FROM sales WHERE id=? AND deleted_at IS NULL');$q->execute([$id]);$sale=$q->fetch()?:[];}$form=in_array($action,['create','edit']);
render_header('Daily Sales','sales');page_title('End-of-Day Sales','DAILY SALES SUMMARY','Enter one daily total and split it into Cash, Card, Talabat, Keeta and Snoonu.',$form?'':'Add Daily Sales',app_url('sales.php?action=create'));
if($form):$branches=options($pdo,'branches');$brands=options($pdo,'brands');?>
<article class="card sales-entry"><div class="card-head"><div><h2><?=$id?'Edit daily sales':'Add end-of-day sales'?></h2><small>One summary for each date, branch and brand.</small></div><span class="status">END OF DAY</span></div><form method="post" data-sales-summary><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="sales-main-fields"><label>Sales Date *<input type="date" name="sale_date" value="<?=e($sale['sale_date']??date('Y-m-d'))?>" max="<?=date('Y-m-d')?>" required></label><label>Branch *<select name="branch_id" required><option value="">Choose branch</option><?php foreach($branches as $x):?><option value="<?=$x['id']?>"<?=selected($sale['branch_id']??'',$x['id'])?>><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Brand *<select name="brand_id" required><option value="">Choose brand</option><?php foreach($brands as $x):?><option value="<?=$x['id']?>"<?=selected($sale['brand_id']??'',$x['id'])?>><?=e($x['label'])?></option><?php endforeach;?></select></label><label class="total-sale-field">Total Sale (QAR) *<input type="number" name="total_amount" inputmode="decimal" min="0.01" step="0.01" value="<?=e($sale['total_amount']??'')?>" placeholder="0.00" required></label></div>
<div class="sales-channels"><label class="cash"><span><i data-icon="cash"></i>Cash Sale</span><input type="number" name="cash_amount" inputmode="decimal" min="0" step="0.01" value="<?=e($sale['cash_amount']??'0')?>"></label><label class="card-pay"><span><i data-icon="card"></i>Card Sale</span><input type="number" name="card_amount" inputmode="decimal" min="0" step="0.01" value="<?=e($sale['card_amount']??'0')?>"></label><label class="talabat"><span>T</span>Talabat Sale<input type="number" name="talabat_amount" inputmode="decimal" min="0" step="0.01" value="<?=e($sale['talabat_amount']??'0')?>"></label><label class="keeta"><span>K</span>Keeta Sale<input type="number" name="keeta_amount" inputmode="decimal" min="0" step="0.01" value="<?=e($sale['keeta_amount']??'0')?>"></label><label class="snoonu"><span>S</span>Snoonu Sale<input type="number" name="snoonu_amount" inputmode="decimal" min="0" step="0.01" value="<?=e($sale['snoonu_amount']??'0')?>"></label></div>
<div class="sales-reconcile" data-sales-reconcile><div><span>Channel total</span><b data-channel-total>QAR 0.00</b></div><div><span>Difference</span><b data-sales-difference>QAR 0.00</b></div><p data-sales-status>Enter the total sale and channel amounts.</p></div><label class="sales-note">Note (optional)<textarea name="notes" rows="2" placeholder="Optional closing note"><?=e($sale['notes']??'')?></textarea></label><div class="form-actions"><a class="btn" href="<?=app_url('sales.php')?>">Cancel</a><button class="btn primary" data-sales-submit><i data-icon="receipt"></i>Save Daily Sales</button></div></form></article>
<?php else:$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$branch=(int)($_GET['branch']??0);$brand=(int)($_GET['brand']??0);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');$where=['s.sale_date BETWEEN ? AND ?','s.deleted_at IS NULL'];$args=[$from,$to];if($branch){$where[]='s.branch_id=?';$args[]=$branch;}if($brand){$where[]='s.brand_id=?';$args[]=$brand;}$q=$pdo->prepare('SELECT s.*,b.name branch,br.name brand,u.name entered_by FROM sales s JOIN branches b ON b.id=s.branch_id JOIN brands br ON br.id=s.brand_id JOIN users u ON u.id=s.created_by WHERE '.implode(' AND ',$where).' ORDER BY s.sale_date DESC,s.id DESC');$q->execute($args);$rows=$q->fetchAll();$totals=['total'=>0,'cash'=>0,'card'=>0,'talabat'=>0,'keeta'=>0,'snoonu'=>0];foreach($rows as $row){$totals['total']+=(float)$row['total_amount'];foreach(['cash','card','talabat','keeta','snoonu'] as $channel)$totals[$channel]+=(float)$row[$channel.'_amount'];}$branches=options($pdo,'branches');$brands=options($pdo,'brands');$thisMonth=['from'=>date('Y-m-01'),'to'=>date('Y-m-d')];$lastMonth=['from'=>date('Y-m-01',strtotime('first day of last month')),'to'=>date('Y-m-t',strtotime('last day of last month'))];?>
<div class="sales-filter-card card"><div class="sales-presets"><a href="?from=<?=date('Y-m-d')?>&to=<?=date('Y-m-d')?>">Today</a><a href="?<?=http_build_query($thisMonth)?>">This Month</a><a href="?<?=http_build_query($lastMonth)?>">Last Month</a></div><form method="get" class="sales-range"><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><label>Branch<select name="branch"><option value="0">All Branches</option><?php foreach($branches as $x):?><option value="<?=$x['id']?>"<?=selected($branch,$x['id'])?>><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Brand<select name="brand"><option value="0">All Brands</option><?php foreach($brands as $x):?><option value="<?=$x['id']?>"<?=selected($brand,$x['id'])?>><?=e($x['label'])?></option><?php endforeach;?></select></label><button class="btn primary">View Sales</button></form></div>
<div class="sales-kpis"><article><span>Total Sales</span><b><?=money($totals['total'])?></b><small><?=date('d M',strtotime($from))?> – <?=date('d M Y',strtotime($to))?></small></article><article><span>Cash</span><b><?=money($totals['cash'])?></b></article><article><span>Card</span><b><?=money($totals['card'])?></b></article><article><span>Delivery Apps</span><b><?=money($totals['talabat']+$totals['keeta']+$totals['snoonu'])?></b></article></div>
<article class="card table-card"><div class="table-toolbar"><div><b><?=count($rows)?> daily sales records</b><small style="display:block;color:var(--muted);margin-top:4px">Complete channel breakdown</small></div><input placeholder="Search sales…" data-table-search></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Branch / Brand</th><th>Total</th><th>Cash</th><th>Card</th><th>Talabat</th><th>Keeta</th><th>Snoonu</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td data-label="Date"><b><?=date('d M Y',strtotime($row['sale_date']))?></b><small style="display:block;color:var(--muted)"><?=e($row['reference_no'])?></small></td><td data-label="Branch / Brand"><?=e($row['branch'])?> · <?=e($row['brand'])?></td><td data-label="Total"><b><?=money($row['total_amount'])?></b></td><td data-label="Cash"><?=money($row['cash_amount'])?></td><td data-label="Card"><?=money($row['card_amount'])?></td><td data-label="Talabat"><?=money($row['talabat_amount'])?></td><td data-label="Keeta"><?=money($row['keeta_amount'])?></td><td data-label="Snoonu"><?=money($row['snoonu_amount'])?></td><td data-label="Action"><a class="btn small" href="?action=edit&id=<?=$row['id']?>">Edit</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="9"><div class="empty"><div class="empty-icon"><i data-icon="receipt"></i></div>No sales records for this date range.</div></td></tr><?php endif;?></tbody></table></div></article><?php endif;render_footer('sales');
